static mut SLOTS: [f64; 4] = [0.0; 4];
/// 1 = written, 0 = refused (slot out of range or NaN). Never panics.
#[unsafe(no_mangle)]
pub extern "C" fn write_slot(i: u32, v: f64) -> u32 {
    if i >= 4 || v.is_nan() {
        return 0;
    }
    let slots = unsafe { &mut *(&raw mut SLOTS) };
    slots[i as usize] = v;
    1
}

